#include "../src/bh_world_load.h"
#include "../src/bh_fp.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static unsigned long checks,failed;
#define CHECK(x,m) do{++checks;if(!(x)){++failed;printf("FAIL world-load %s line%d\n",m,__LINE__);}}while(0)
#include "editor_control_fixture.h"
typedef struct LoadFixture {EditorFixture editor;BHScriptLifetimeContext life;BHScriptVMContext vm;BHScriptTimerActor states[64];BHScriptVMActor actors[64];BHScriptVMWaypoint waypoints[8];BHRailPaths rails;BHWorldLoad loader;} LoadFixture;
static int setup(LoadFixture *f){EditorFixture *e=&f->editor;memset(f,0,sizeof(*f));if(!editor_fixture(e)||!bh_editor_world_dispose(&e->world)||!bh_rail_paths_init(&f->rails,0))return 0;f->life.timers.pool=&e->pool;f->life.sounds=&e->sound;f->vm.lifetime=&f->life;f->vm.actors=f->actors;f->vm.waypoints=f->waypoints;f->vm.waypoint_count=8;f->loader.editor=&e->control;f->loader.vm=&f->vm;f->loader.rails=&f->rails;f->loader.states=f->states;f->loader.actor_capacity=64;return 1;}
static void dispose(LoadFixture *f){editor_finish(&f->editor);bh_rail_paths_dispose(&f->rails);}
static void record(FILE *f,const char *name,long x,long y,long z,long flags){char text[16];long v[4];memset(text,0,16);strncpy(text,name,16);v[0]=x;v[1]=y;v[2]=z;v[3]=flags;fwrite(text,16,1,f);fwrite(v,16,1,f);}
static void override(FILE *f,unsigned long id,short v){short vars[8];memset(vars,0,sizeof(vars));vars[0]=v;fwrite(&id,4,1,f);fwrite(vars,16,1,f);}
static BHEntity *script(LoadFixture *f,long opcode,int variable){long args[5]={0,30,4,0,0},select[5]={-1,-1,-1,-1,-1};if(variable)select[0]=0;return bh_script_vm_create(&f->vm,0,opcode,args,select);}
int bh_world_load_checkpoint(unsigned long *count){LoadFixture f;EditorFixture *e=&f.editor;BHMathEnvironment env;FILE *file;long n;unsigned long i,rng,matched;BHEditorNode *root,*child,*last;BHEntity *a,*b,*timer;
 checks=failed=0;CHECK(bh_math_environment_enter(&env),"PC53");CHECK(setup(&f),"real typed editor/VM/rail closure");strcpy(e->blocks[1].definition.name,"RC_0");a=script(&f,20,1);b=script(&f,19,1);e->blocks[0].definition.script=a;e->blocks[1].definition.script=b;CHECK(a&&b,"real startup script templates");e->blocks[0].definition.values[0]=0;
 file=fopen("world-load-fixture.lev","wb");CHECK(file!=0,"fixture file");n=4;fwrite(&n,4,1,file);record(file,"SEGMENT.BSP",0,0,0,1);record(file,"missing",99,98,97,3);record(file,"rc_0",6,0,0,0);record(file,"segment.bsp",20,0,0,3);override(file,3,1);override(file,1,999);override(file,2,42);override(file,3,2);fclose(file);
 srand(71);for(i=0;i<2;++i)rand();rng=rand();srand(71);CHECK(bh_world_load(&f.loader,"world-load-fixture.lev"),"whole loader");CHECK(rand()==rng,"only immediate timers consume shared RNG");CHECK(e->world.count==3&&f.loader.skipped==1&&f.loader.overrides==3,"original placement IDs and wrapped override search");CHECK(e->world.mode==2&&e->world.selection==e->world.nodes[0]&&e->world.nodes[0]->entity->step==bh_editor_tick,"real first editor callback installed, mode2");root=e->world.nodes[0];child=e->world.nodes[1];last=e->world.nodes[2];CHECK(root->placement.geometry.previous==&last->placement.geometry&&last->placement.geometry.navigation.next==&root->placement.geometry.navigation,"source reciprocal ring closure");CHECK(word(root->entity,0x120)==(unsigned long)last->entity&&word(last->entity,0x124)==(unsigned long)root->entity,"actual original entity ring");CHECK(root->entity->kind==1&&word(root->entity,0x118)==0&&word(child->entity,0x118)==2&&word(last->entity,0x118)==3,"class and sparse original indices");CHECK(root->placement.coordinates[0]==0&&child->placement.coordinates[0]==6&&last->entity->position.x==20,"unsnapped original placement coordinates");CHECK(word(root->entity,0x114)==6&&word(child->entity,0x11c)==0xffffffffUL&&number(root->entity,0x13c)==250&&word(child->entity,0x13c)==0x437a0000,"real initialization fields and orbit");CHECK(f.loader.timers==3&&f.loader.immediate==2,"startup templates scheduled and leading location immediate");CHECK(f.waypoints[0].position.x==0&&f.waypoints[2].position.x==20&&f.waypoints[1].speed==0&&f.waypoints[2].speed==30,"last saved override precedes immediate source VM");CHECK(f.states[1].variables[0]==42&&f.states[2].variables[0]==2&&f.vm.actor_count==3&&f.life.timers.actor_count==3,"stable actual timer/VM actor tables");CHECK(child->placement.geometry.owner==&root->placement.geometry&&word(child->entity,0x1c8)==(unsigned long)root->entity&&f.states[1].owner==f.states,"real geometry pass and typed owner mapping");matched=0;for(i=0;i<6;++i)if(root->placement.geometry.navigation.portals[i].neighbor==&last->placement.geometry.navigation)++matched;CHECK(root->placement.geometry.navigation.count==6&&last->placement.geometry.navigation.count==6&&matched==1,"actual six-portal match after all builds");CHECK(f.rails.placements==3&&f.rails.count>0&&f.rails.chain_count>0,"real name-based rail extraction and link");CHECK(root->entity->refresh==bh_editor_world_draw_callback()&&child->entity->step==0&&last->entity->step==0,"only actual source callbacks and verified empty steps");
 timer=e->pool.active;CHECK(timer->step==bh_script_timer_unconditional_step()&&word(timer,0xf0)==(unsigned long)child->entity,"deferred timer real actor");timer->step(timer);CHECK(word(root->entity,0x11c)==42&&word(child->entity,0x11c)==0xffffffffUL&&e->pool.used==5,"actual deferred startup VM and one-shot release");for(i=0;i<3;++i)CHECK(number(e->world.nodes[i]->entity,0xb4)==100000,"full ring priority");CHECK(!bh_world_load(&f.loader,"world-load-fixture.lev")&&f.loader.error==1,"fresh-owner precondition preserves live scene");dispose(&f);
 CHECK(setup(&f),"empty fixture");file=fopen("world-load-fixture.lev","wb");n=0;fwrite(&n,4,1,file);fclose(file);CHECK(bh_world_load(&f.loader,"world-load-fixture.lev")&&!e->world.count&&e->world.mode==1,"zero header closes and leaves mode untouched");CHECK(!bh_world_load(&f.loader,"missing-world-load.lev")&&f.loader.error==2,"missing VFILE");file=fopen("world-load-fixture.lev","wb");n=1;fwrite(&n,4,1,file);record(file,"missing",0,0,0,0);fclose(file);CHECK(!bh_world_load(&f.loader,"world-load-fixture.lev")&&f.loader.error==3&&f.loader.skipped==1&&!e->world.count,"all-unknown bounded source error");dispose(&f);
 CHECK(setup(&f),"malformed fixture");file=fopen("world-load-fixture.lev","wb");n=1;fwrite(&n,4,1,file);record(file,"segment.bsp",3,1,-3,0);fwrite(&n,1,1,file);fclose(file);CHECK(!bh_world_load(&f.loader,"world-load-fixture.lev")&&f.loader.error==3&&e->world.count==1&&e->world.mode==1,"truncated overrides reject with prior construction retained");dispose(&f);remove("world-load-fixture.lev");bh_math_environment_leave(&env);if(count)*count=checks;printf("{\"scenario\":\"world-load\",\"checks\":%lu,\"failures\":%lu,\"original_code_required\":false}\n",checks,failed);return failed!=0;
}
